(function() {
    var t = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
    var l = (navigator.language || '').toLowerCase();
    var isJapan = (t === 'Asia/Tokyo') || (l.indexOf('ja') === 0);

    if (!isJapan) {
        var hideStyle = document.createElement('style');
        hideStyle.type = 'text/css';
        hideStyle.innerHTML = 
            '#vdbanner, div[id*="vdbanner"], iframe[src*="xrea"], iframe[src*="value-domain"] {' +
                'display: none !important;' +
                'visibility: hidden !important;' +
                'height: 0 !important;' +
                'width: 0 !important;' +
                'position: absolute !important;' +
                'top: -9999px !important;' +
                'left: -9999px !important;' +
                'overflow: hidden !important;' +
                'pointer-events: none !important;' +
            '}' +
            'body { margin: 0 !important; padding: 0 !important; }';
        (document.head || document.documentElement).appendChild(hideStyle);

        document.addEventListener('DOMContentLoaded', function() {
            var observer = new MutationObserver(function(mutations) {
                var ads = document.querySelectorAll('#vdbanner, div[id*="vdbanner"], iframe[src*="xrea"], iframe[src*="value-domain"]');
                ads.forEach(function(el) {
                    if (el.style.display !== 'none') {
                        el.style.setProperty('display', 'none', 'important');
                        el.style.setProperty('height', '0', 'important');
                    }
                });
            });
            if (document.body) {
                observer.observe(document.body, { childList: true, subtree: true, attributes: true });
            }
        });
    }
})();
